from rest_framework import viewsets, permissions
from rest_framework.renderers import JSONRenderer
from rest_framework_xml.renderers import XMLRenderer
from .models import PatientClinicalRecord
from .serializers import ClinicalRecordSerializer

class ClinicalRecordViewSet(viewsets.ReadOnlyModelViewSet):
    permission_classes = [permissions.IsAuthenticated]
    serializer_class = ClinicalRecordSerializer
    renderer_classes = [JSONRenderer, XMLRenderer]

    def get_queryset(self):
        # Enforce physician scoping across all renderers unless staff with exchange privilege
        if self.request.user.is_staff and self.request.user.has_perm('ehr.export_all_xml'):
            return PatientClinicalRecord.objects.all()
        return PatientClinicalRecord.objects.filter(primary_physician=self.request.user)
